package com.example.domain.model.i18n

internal object DuaPt4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_ishfi_abdak" to DuaText("Pela cura de um doente", "Ó Allah, cura Teu servo para que ele enfrente um inimigo por Ti ou marche para a oração por Ti.", "Para o doente durante uma visita.", "O Profeta ﷺ ensinava a dizer isso pelo doente."),
        "dua_ism_azam_ahad_samad" to DuaText("O Nome Supremo: Al-Ahad As-Samad", "Ó Allah, peço-Te, pois testemunho que Tu és Allah; não há divindade senão Tu, o Único, o Absoluto, que jamais gerou nem foi gerado, e ninguém é igual a Ele.", "O Profeta ﷺ disse que aquele homem havia pedido a Allah por Seu Nome Supremo.", "Quando se pede por este Nome, Ele dá; quando se O invoca por ele, Ele responde."),
        "dua_ism_azam_mannan" to DuaText("O Nome Supremo: Al-Mannan", "Ó Allah, peço-Te, pois a Ti pertence todo o louvor; não há divindade senão Tu, o Doador de favores, Criador dos céus e da terra. Ó Detentor de Majestade e Honra, ó Vivente, ó Sustentador!", "O Profeta ﷺ disse que este homem havia invocado pelo Nome Supremo de Allah.", "Uma súplica feita por este Nome é atendida."),
        "dua_istiftah_baid" to DuaText("Súplica de abertura: afasta-me dos pecados", "Ó Allah, afasta-me dos meus pecados como afastaste o Oriente do Ocidente. Ó Allah, purifica-me dos meus pecados como se purifica um pano branco da sujeira. Ó Allah, lava meus pecados com água, neve e granizo.", "Após o takbir de abertura (pode substituir a Sana).", "O Profeta ﷺ a recitava entre o takbir e a recitação."),
        "dua_istiftah_kabira" to DuaText("Allah é o Maior, abundantemente louvado", "Allah é o Maior, grandemente; abundante louvor a Allah; e glória a Allah de manhã e à noite.", "No início da oração (uma das formas de abertura).", "O Profeta ﷺ disse: as portas do céu se abriram para isto."),
        "dua_istisqa" to DuaText("Pedir chuva (Istisqa)", "Ó Allah, envia-nos chuva (três vezes).", "Quando não chove.", "O Profeta ﷺ fez esta súplica no sermão de sexta-feira e choveu."),
        "dua_istisqa_ibadak" to DuaText("Dá água a Teus servos e a seus animais", "Ó Allah, dá água a Teus servos e a Teus animais, espalha Tua misericórdia e revive Tua terra morta.", "Para pedir chuva (istisqa).", "O Profeta ﷺ fez esta súplica pela chuva."),
        "dua_jahdil_bala" to DuaText("Refúgio contra provações severas", "Ó Allah, busco refúgio em Ti contra a provação severa, contra ser alcançado pela desgraça, contra um mau decreto e contra o escárnio dos inimigos.", "Proteção contra provações severas e o escárnio dos inimigos.", "O Profeta ﷺ buscava refúgio contra estas quatro coisas."),
        "dua_jamarat" to DuaText("O lançamento das Jamarat", "Allah é o Maior.", "A cada pedra lançada.", "O Profeta ﷺ dizia o takbir a cada pedra, e depois da primeira e segunda jamra, virava-se para a Qibla para uma longa súplica."),
        "dua_janaza_adult" to DuaText("Oração fúnebre (adulto)", "Ó Allah, perdoa aos nossos vivos e mortos, aos presentes e ausentes, aos nossos jovens e idosos, aos nossos homens e mulheres. Ó Allah, aquele de nós que mantiveres vivo, mantém-no vivo no Islã, e aquele de nós que fizeres morrer, faze-o morrer na fé.", "Após o terceiro takbir da oração fúnebre.", "A súplica profética para um falecido adulto."),
        "dua_janaza_child" to DuaText("Oração fúnebre (criança)", "Ó Allah, faze dele um precursor (e uma acolhida) para nós, faze dele para nós uma recompensa e um tesouro, e faze dele para nós um intercessor cuja intercessão seja aceita.", "Na oração fúnebre de uma criança (para uma menina dizer 'ij'alha').", "A súplica praticada pelos Hanafitas."),
        "dua_jannah_nar" to DuaText("Pedido do Paraíso, refúgio contra o Fogo", "Ó Allah, peço-Te o Paraíso e busco refúgio em Ti contra o Fogo.", "Após o tashahhud ou a qualquer momento.", "O Profeta ﷺ disse: nossas súplicas também giram em torno disso."),
        "dua_jar_su" to DuaText("Refúgio contra um mau vizinho", "Ó Allah, busco refúgio em Ti contra um mau vizinho no local de residência permanente, pois o vizinho de viagem acaba indo embora.", "Para ser protegido de um mau vizinho.", "O Profeta ﷺ ordenou buscar refúgio contra isso."),
        "dua_jiddi_wa_hazli" to DuaText("Perdoa meus pecados sérios e em brincadeira", "Ó Allah, perdoa-me os pecados que cometi seriamente e brincando, por erro e deliberadamente — tudo isso está em mim.", "Perdão para todo tipo de pecado, conhecido e desconhecido.", "Um istighfar completo do Profeta ﷺ."),
        "dua_ju_khiyanah" to DuaText("Refúgio contra a fome e a traição", "Ó Allah, busco refúgio em Ti contra a fome, pois é um mau companheiro, e busco refúgio em Ti contra a traição, pois é um mau confidente.", "Proteção contra a fome e a traição.", "Uma súplica de proteção do Profeta ﷺ."),
        "dua_khayri_kullih" to DuaText("Todo o bem, agora e depois", "Ó Allah, peço-Te todo o bem — o imediato e o adiado, o que conheço e o que não conheço — e busco refúgio em Ti contra todo o mal — o imediato e o adiado, o que conheço e o que não conheço. Ó Allah, peço-Te o Paraíso e tudo o que, em palavra ou ação, me aproxima dele, e busco refúgio em Ti contra o Fogo e tudo o que, em palavra ou ação, me aproxima dele.", "O Profeta ﷺ ensinou esta súplica completa a Aisha (RA) (parte da súplica).", "Uma súplica que reúne todo o bem."),
        "dua_kufr_faqr" to DuaText("Refúgio contra a descrença e a pobreza", "Ó Allah, busco refúgio em Ti contra a descrença e a pobreza, e busco refúgio em Ti contra o castigo da sepultura. Não há divindade senão Tu.", "Três vezes de manhã e à noite.", "Abu Bakrah (RA) ouviu o Profeta ﷺ dizer isso."),
        "dua_la_bas_tahur" to DuaText("Consolar o doente: uma purificação", "Não é nada; é uma purificação (dos pecados), se Allah quiser.", "Para consolar o doente em uma visita.", "O Profeta ﷺ dizia isso ao visitar os doentes."),
        "dua_la_hawla_kanz" to DuaText("Um tesouro do Paraíso", "Não há força nem poder senão em Allah.", "Frequentemente, em toda ocasião.", "É um dos tesouros do Paraíso."),
        "dua_la_mania" to DuaText("Ninguém pode reter o que Tu dás", "Não há divindade digna de adoração senão Allah, Único, sem associado. D'Ele é o domínio, a Ele pertence o louvor, e Ele é capaz de todas as coisas. Ó Allah, ninguém pode reter o que Tu dás e ninguém pode dar o que Tu retens, e a riqueza do rico não serve de nada contra Ti.", "Após a saudação da oração obrigatória.", "O Profeta ﷺ dizia isso após cada oração obrigatória."),
        "dua_leaving_home_adilla" to DuaText("Refúgio ao sair de casa", "Ó Allah, busco refúgio em Ti contra me extraviar ou ser extraviado, tropeçar ou ser feito tropeçar, cometer uma injustiça ou sofrê-la, agir com tolice ou ser tratado com tolice.", "Ao sair de casa — relatado por Umm Salamah (RA).", "O Profeta ﷺ a recitava sempre que saía de casa."),
        "dua_leprosy_diseases" to DuaText("Refúgio contra doenças graves", "Ó Allah, busco refúgio em Ti contra o vitiligo, a loucura, a lepra e todas as doenças graves.", "Proteção contra doenças graves.", "Uma súplica profética para preservar a saúde."),
        "dua_love_for_allah" to DuaText("Quando dizem 'eu te amo por Allah'", "Que Aquele por quem me amas te ame.", "Quando alguém diz 'eu te amo por Allah'.", "A resposta profética ao amor por Allah."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Perdoa meus pecados de antes e depois", "Ó Allah, perdoa-me os pecados que cometi antes e depois, o que fiz em segredo e o que fiz abertamente, meus excessos, e o que Tu conheces melhor que eu. Tu és Aquele que adianta e Aquele que atrasa; não há divindade senão Tu.", "Após o tashahhud e as saudações, antes do salam.", "O Profeta ﷺ a recitava no final da oração, entre o tashahhud e o salam."),
        "dua_mayyit_awf" to DuaText("Súplica detalhada pelo falecido", "Ó Allah, perdoa-lhe, tem misericórdia dele, concede-lhe o bem-estar e perdoa-o. Honra sua acolhida, alarga sua sepultura, lava-o com água, neve e granizo, e purifica-o de seus pecados como se purifica um pano branco da sujeira.", "Na oração fúnebre ou pelo falecido.", "Awf ibn Malik (RA) teria desejado ser esse falecido."),
        "dua_morning_blessing" to DuaText("Gratidão da manhã pelos favores", "Ó Allah, todo favor que eu ou qualquer uma de Tuas criaturas recebemos nesta manhã vem de Ti só, sem associado; a Ti, pois, todo o louvor e todo o agradecimento.", "Dhikr matinal de gratidão pelos favores de Allah.", "Reconhecer que todo bem vem exclusivamente de Allah."),
        "dua_morning_witness" to DuaText("Testemunho da manhã sobre o tawhid", "Ó Allah, entro na manhã tomando-Te, os portadores de Teu Trono, Teus anjos e toda a Tua criação como testemunhas de que Tu és Allah, não há divindade senão Tu, Único, sem associado, e que Muhammad ﷺ é Teu servo e Mensageiro.", "A narração menciona dizer isso quatro vezes pela manhã.", "Quem o disser, Allah o libertará de uma parte do Fogo."),
        "dua_muawwidhat" to DuaText("Os três Qul (Al-Mu'awwidhat)", "(Surata Al-Ikhlas) Dize: Ele é Allah, o Único. Allah, o Absoluto, a quem se recorre em toda necessidade. Ele não gerou nem foi gerado. E não há ninguém que se iguale a Ele.\n\n(Surata Al-Falaq) Dize: Busco refúgio no Senhor da alvorada, contra o mal do que Ele criou, contra o mal da escuridão quando se instala, contra o mal das que sopram nos nós, e contra o mal do invejoso quando inveja.\n\n(Surata An-Nas) Dize: Busco refúgio no Senhor dos homens, o Rei dos homens, Deus dos homens, contra o mal do sussurrador furtivo, que sopra o mal nos peitos dos homens, seja dos gênios ou dos homens.", "Recitar estas três suratas três vezes cada manhã e noite, e antes de dormir soprar nas mãos e passá-las pelo corpo.", "Recitá-las três vezes de manhã e à noite basta contra tudo."),
        "dua_musa_faqir" to DuaText("Súplica de Musa (AS) pelo sustento", "Senhor, tenho grande necessidade do bem que farás descer sobre mim.", "Pedido de sustento e bem — a súplica de Musa (AS) em Madyan.", "Após esta súplica, Allah concedeu a Musa (AS) um lar, um trabalho e uma esposa."),
        "dua_musarrifal_qulub" to DuaText("Tu que reviras os corações", "Ó Allah, Tu que reviras os corações, vira nossos corações para Tua obediência.", "Uma súplica para manter o coração firme na obediência.", "Os corações de todos os homens estão entre dois dedos do Todo-Misericordioso."),
        "dua_new_moon" to DuaText("Ao ver a lua nova", "Ó Allah, faze que esta lua surja sobre nós com bênção, fé, segurança e islã. (Ó lua,) meu Senhor e teu Senhor é Allah.", "Ao ver a lua nova.", "A súplica profética para cada novo mês."),
        "dua_non_muslim_sneezes" to DuaText("Quando um não-muçulmano espirra", "Que Allah te guie e corrija teu estado.", "Quando um não-muçulmano espirra e diz 'Alhamdulillah'.", "Judeus espirravam perto do Profeta ﷺ esperando que ele dissesse 'Yarhamukallah', e ele dizia isso."),
        "dua_placing_in_grave" to DuaText("Ao depositar o falecido na sepultura", "Em nome de Allah e segundo o caminho do Mensageiro de Allah ﷺ.", "Ao descer o falecido na sepultura.", "A súplica profética do enterro."),
        "dua_praising_someone" to DuaText("Ao elogiar alguém", "Considero fulano como sendo assim, e Allah é seu juiz, e não garanto a pureza de ninguém diante de Allah.", "Ao elogiar alguém, em vez de exagerar.", "O Profeta ﷺ ensinou esta etiqueta do elogio."),
        "dua_q_alayka_tawakkalna" to DuaText("Em Ti nos apoiamos (Ibrahim AS)", "Nosso Senhor, em Ti nos apoiamos, a Ti nos voltamos e a Ti é o retorno. Nosso Senhor, não faças de nós uma provação para os descrentes e perdoa-nos. Nosso Senhor, Tu és o Todo-Poderoso, o Sábio.", "A súplica de Ibrahim (AS) e seus companheiros.", "Uma súplica de confiança em Allah e retorno a Ele."),
        "dua_q_amanna_faghfir" to DuaText("Cremos, perdoa-nos", "Nosso Senhor, cremos, perdoa-nos então e tem misericórdia de nós, pois Tu és o melhor dos misericordiosos.", "A súplica dos servos virtuosos de Allah.", "Uma súplica completa pelo perdão e misericórdia."),
        "dua_q_aqraba_rashada" to DuaText("Que meu Senhor me guie a uma conduta melhor", "Talvez meu Senhor me guie a uma conduta mais próxima da retidão do que esta.", "Ao buscar um caminho melhor em um assunto.", "O Profeta ﷺ recebeu a ordem de dizer isso em caso de esquecimento."),
        "dua_q_ashku_bathhi" to DuaText("Súplica de Ya'qub (AS) — Só me queixo a Allah", "Só me queixo de minha angústia e tristeza a Allah.", "No luto profundo e na separação.", "Ya'qub (AS) disse isso ao se separar de Yusuf (AS)."),
        "dua_q_asiya_baytan" to DuaText("Súplica de Asiya — Uma casa no Paraíso", "Meu Senhor, constrói para mim junto a Ti uma casa no Paraíso, salva-me do Faraó e de seus atos, e salva-me do povo injusto.", "A súplica de Asiya, esposa do Faraó.", "Allah fez dela um exemplo para os crentes."),
        "dua_q_atina_ma_waadtana" to DuaText("Concede-nos o que nos prometeste", "Nosso Senhor, concede-nos o que nos prometeste por meio de Teus mensageiros, e não nos cubras de vergonha no Dia da Ressurreição. Certamente Tu nunca faltas com Tua promessa.", "Proteção contra a vergonha no Dia da Ressurreição.", "Buscar a honra no além."),
        "dua_q_atmim_nurana" to DuaText("Completa nossa luz", "Nosso Senhor, completa para nós nossa luz e perdoa-nos. Tu és capaz de todas as coisas.", "A súplica dos crentes no Dia da Ressurreição.", "Pedir a luz sobre o Sirat."),
        "dua_q_do_not_make_us_trial" to DuaText("Não faças de nós uma provação", "Nosso Senhor, não faças de nós uma provação para os descrentes, e perdoa-nos, nosso Senhor. Tu és o Todo-Poderoso, o Sábio.", "A súplica de Ibrahim (AS) e seus companheiros.", "Proteção contra a opressão dos descrentes."),
        "dua_q_hab_li_hukman" to DuaText("Súplica de Ibrahim (AS) — Sabedoria e Paraíso", "Meu Senhor, concede-me sabedoria e junta-me aos virtuosos, concede-me uma menção honrosa entre as gerações futuras, e faze-me um dos herdeiros do Jardim das delícias.", "Pedir sabedoria, a companhia dos virtuosos e o Paraíso.", "Uma súplica completa de Ibrahim (AS)."),
        "dua_q_hab_li_salihin" to DuaText("Súplica de Ibrahim (AS) por um filho virtuoso", "Meu Senhor, concede-me (um filho) entre os virtuosos.", "Pedir filhos virtuosos.", "Por esta súplica, Ismail (AS) foi concedido."),
        "dua_q_hawariyyun" to DuaText("Súplica dos discípulos — Inscreve-nos entre as testemunhas", "Nosso Senhor, cremos no que revelaste e seguimos o Mensageiro, inscreve-nos então entre as testemunhas.", "Pela firmeza na fé e no seguimento do Mensageiro.", "A súplica dos discípulos de Issa (AS)."),
        "dua_q_iftah_baynana" to DuaText("Súplica de Shu'ayb (AS) — Julga entre nós", "Nosso Senhor, julga entre nós e nosso povo com verdade, e Tu és o melhor dos juízes.", "Por um julgamento entre verdade e mentira.", "A súplica de Shu'ayb (AS) quando seu povo o rejeitou."),
        "dua_q_ihkum_bil_haqq" to DuaText("Meu Senhor, julga com verdade", "Meu Senhor, julga com verdade. E nosso Senhor é o Todo-Misericordioso, cujo socorro é implorado contra o que descreveis.", "Diante de mentiras e falsas acusações.", "Uma súplica ensinada ao Profeta ﷺ."),
        "dua_q_ikhwanina" to DuaText("Por nossos irmãos que nos precederam", "Nosso Senhor, perdoa-nos e a nossos irmãos que nos precederam na fé, e não coloques em nossos corações nenhum rancor contra os que creram. Nosso Senhor, Tu és Compassivo e Misericordioso.", "Uma súplica pelos crentes passados e por um coração puro.", "Uma súplica pelos nobres Companheiros (RA) e crentes anteriores."),
        "dua_q_israfana" to DuaText("Perdoa nossos excessos", "Nosso Senhor, perdoa-nos nossos pecados e nossos excessos em nossos assuntos, firma nossos passos e concede-nos a vitória sobre os descrentes.", "A súplica dos companheiros dos Profetas anteriores.", "Uma súplica pela firmeza e pelo perdão."),
        "dua_q_isrif_jahannam" to DuaText("Afasta de nós o castigo do Inferno", "Nosso Senhor, afasta de nós o castigo do Inferno, pois seu castigo é permanente. Que morada e lugar de residência ruins.", "A súplica dos servos do Todo-Misericordioso ('Ibad ar-Rahman).", "Uma súplica alcorânica para ser preservado do Inferno."),
        "dua_q_jamiun_nas" to DuaText("Tu reunirás a humanidade", "Nosso Senhor, certamente reunirás os homens em um dia sobre o qual não há dúvida. Certamente Allah não falta com Sua promessa.", "Afirmar a certeza do Dia da Ressurreição.", "A súplica dos que estão firmemente enraizados no saber."),
        "dua_q_khayrun_hafiza" to DuaText("Allah é o melhor protetor", "Allah é o melhor Protetor, e Ele é o mais Misericordioso dos misericordiosos.", "Ao enviar os filhos ou entes queridos em viagem.", "Ya'qub (AS) disse isso ao confiar seu filho a Allah."),
        "dua_q_la_akuna_zahiran" to DuaText("Súplica de Musa (AS) — Nunca um apoio para os criminosos", "Meu Senhor, por causa do favor com que me agraciaste, nunca serei um apoio para os criminosos.", "Gratidão pelos favores de Allah e compromisso de não ajudar os injustos.", "O compromisso de Musa (AS) após seu arrependimento."),
        "dua_q_la_tadharni_fardan" to DuaText("Súplica de Zakariya (AS) — Não me deixes só", "Meu Senhor, não me deixes só, pois Tu és o melhor dos herdeiros.", "Para quem deseja ter filhos.", "Por esta súplica, Allah concedeu Yahya (AS)."),
        "dua_q_la_tajalna_fitnah" to DuaText("Não faças de nós uma provação para os injustos", "É em Allah que depositamos nossa confiança. Nosso Senhor, não faças de nós uma provação para os injustos, e salva-nos por Tua misericórdia dos descrentes.", "A súplica do povo de Musa (AS).", "Uma súplica para ser libertado da opressão e dos opressores."),
        "dua_q_la_tajalna_zalimin" to DuaText("Não nos coloques entre os injustos", "Nosso Senhor, não nos coloques entre os injustos.", "A súplica do povo de al-A'raf.", "Proteção contra o destino dos injustos."),
        "dua_q_la_tukhzini" to DuaText("Súplica de Ibrahim (AS) — Não me cubras de vergonha", "E não me cubras de vergonha no dia em que forem ressuscitados.", "Para ser preservado da vergonha no Dia da Ressurreição.", "A súplica de Ibrahim (AS) pelo além."),
        "dua_q_lut_najjini_ahli" to DuaText("Súplica de Lut (AS) — Salva minha família", "Meu Senhor, salva-me e a minha família do que fazem.", "Proteger a família de um ambiente corrompido.", "Proteção da família contra o mal."),
        "dua_q_lut_unsurni" to DuaText("Súplica de Lut (AS) — Ajuda-me contra os corruptores", "Meu Senhor, ajuda-me contra o povo corruptor.", "Para obter ajuda contra aqueles que espalham a corrupção.", "A súplica dos que permanecem firmes na verdade."),
        "dua_q_ma_khalaqta_batila" to DuaText("Meditar sobre a criação", "Nosso Senhor, não criaste tudo isso em vão. Glória a Ti, protege-nos então do castigo do Fogo.", "A súplica dos que meditam sobre a criação dos céus e da terra.", "A súplica dos dotados de entendimento (ulul-albab)."),
        "dua_q_maash_shahidin" to DuaText("Inscreve-nos entre as testemunhas", "Nosso Senhor, cremos, inscreve-nos então entre as testemunhas.", "A súplica dos que reconheceram a verdade e creram.", "Uma súplica pela aceitação de sua fé."),
        "dua_q_mudkhala_sidq" to DuaText("Entrada e saída de verdade", "Meu Senhor, faze-me entrar por uma entrada de verdade e sair por uma saída de verdade, e concede-me de Tua parte uma autoridade que me sustente.", "Antes de empreender uma nova tarefa, um novo lar ou um novo lugar.", "A súplica ensinada ao Profeta ﷺ no momento da Hégira."),
        "dua_q_munzalan_mubarakan" to DuaText("Um lugar de pouso abençoado", "Meu Senhor, faze-me descer em um lugar abençoado, pois Tu és o melhor daqueles que fazem descer.", "Ao se instalar em um novo lar ou fazer pouso em algum lugar — a súplica de Nuh (AS).", "Uma súplica pela bênção em um novo lugar."),
        "dua_q_musa_li_akhi" to DuaText("Súplica de Musa (AS) — Perdoa-me e a meu irmão", "Meu Senhor, perdoa-me e a meu irmão, e faze-nos entrar em Tua misericórdia, pois Tu és o mais Misericordioso dos misericordiosos.", "Perdão para si mesmo e para seu irmão ou parentes.", "A súplica de Musa (AS) por Harun (AS)."),
        "dua_q_musa_najjini" to DuaText("Súplica de Musa (AS) — Salva-me dos opressores", "Meu Senhor, salva-me do povo injusto.", "Quando se teme opressores.", "A súplica de Musa (AS) ao deixar o Egito."),
        "dua_q_musa_zalamtu" to DuaText("Súplica de Musa (AS) — Fiz mal a mim mesmo", "Meu Senhor, fiz mal a mim mesmo, perdoa-me então.", "Arrependimento imediato após uma falta.", "Allah perdoou Musa (AS)."),
        "dua_q_muslimayni_laka" to DuaText("Súplica de Ibrahim e Ismail (AS) — Faze de nós submissos", "Nosso Senhor, faze de nós dois submissos a Ti, e de nossa descendência uma comunidade submissa a Ti. Mostra-nos nossos ritos e aceita nosso arrependimento. Tu és o Aceitador do arrependimento, o Misericordioso.", "Uma súplica de submissão para si mesmo e sua descendência.", "A súplica feita ao construir a Caaba."),
        "dua_q_not_among_wrongdoers" to DuaText("Não me coloques entre os injustos", "Meu Senhor, não me coloques entre o povo injusto.", "Uma súplica pedindo a Allah que nos mantenha afastados dos injustos.", "Proteção contra o destino dos que praticam injustiça."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Súplica de arrependimento de Nuh (AS)", "Meu Senhor, busco proteção em Ti contra pedir-Te aquilo de que não tenho conhecimento. E a menos que me perdoes e tenhas misericórdia de mim, serei dos perdedores.", "A súplica de arrependimento do profeta Nuh (AS).", "Uma lição sobre como pedir com correção."),
        "dua_q_nuh_unsurni" to DuaText("Súplica de Nuh (AS) — Ajuda-me, negaram-me", "Meu Senhor, ajuda-me, pois me trataram como mentiroso.", "Quando as pessoas o negam e rejeitam a verdade.", "A súplica de Nuh (AS), que foi atendida.")
    )
}
